#!/usr/bin/env python3
"""Reset the document properties of a NEW .docx/.xlsx/.pptx created with python-docx,
openpyxl or python-pptx.

Those libraries leave junk metadata: author "python-docx"/"openpyxl", description
"generated by python-docx", "lastModifiedBy: Steve Canny", creation dates from 2013.
This script clears it: author/lastModifiedBy set to --author (default: empty),
description/keywords/category/subject emptied, created/modified set to now.
The title is kept unless --title is given.

Usage:
    python clean_metadata.py FILE [--author "Nombre Apellido"] [--title "..."]

Use it only on files you created from scratch. For a template or file the student
gave you, keep its original properties (that's part of the minimal-change rule).

Standard library only. Rewrites the file in place.
"""
import argparse
import sys
import datetime
import os
import re
import shutil
import tempfile
import zipfile
from xml.sax.saxutils import escape


def main():
    # Windows consoles default to cp1252; don't crash on accents or symbols.
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(errors="replace")
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("file")
    ap.add_argument("--author", default="")
    ap.add_argument("--title", default=None)
    a = ap.parse_args()

    now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    with zipfile.ZipFile(a.file) as z:
        items = [(i, z.read(i.filename)) for i in z.infolist()]
    names = [i.filename for i, _ in items]
    if "docProps/core.xml" not in names:
        print("No docProps/core.xml found; nothing to clean.")
        return

    title = None
    for i, data in items:
        if i.filename == "docProps/core.xml":
            m = re.search(rb"<dc:title>(.*?)</dc:title>", data, re.S)
            title = m.group(1).decode("utf-8") if m else ""
    if a.title is not None:
        title = escape(a.title)
    author = escape(a.author)

    core = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
        '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
        'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" '
        'xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
        f"<dc:title>{title or ''}</dc:title><dc:creator>{author}</dc:creator>"
        f"<cp:lastModifiedBy>{author}</cp:lastModifiedBy><cp:revision>1</cp:revision>"
        f'<dcterms:created xsi:type="dcterms:W3CDTF">{now}</dcterms:created>'
        f'<dcterms:modified xsi:type="dcterms:W3CDTF">{now}</dcterms:modified>'
        "</cp:coreProperties>"
    ).encode("utf-8")

    fd, tmp = tempfile.mkstemp(suffix=os.path.splitext(a.file)[1])
    os.close(fd)
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as out:
        for info, data in items:
            if info.filename == "docProps/core.xml":
                data = core
            out.writestr(info, data)
    shutil.move(tmp, a.file)
    print(f"Metadata reset: {a.file} (author={a.author!r}, dates={now})")


if __name__ == "__main__":
    main()
